const feedback = document.getElementById('ai4a11y-voice-feedback');
const style = document.getElementById('ai4a11y-voice-pulse-style');
const vc = window.__ai4a11yVoiceCommands;

if (!vc || !vc.enabled) {
  return feedback === null && style === null;
}

if (!feedback || !style) return false;
if (feedback.getAttribute('aria-hidden') !== 'true') return false;
if (window.getComputedStyle(feedback).pointerEvents !== 'none') return false;

const dot = feedback.querySelector('.ai4a11y-voice-dot');
const text = feedback.querySelector('.ai4a11y-voice-text');
if (!dot || !text || !text.textContent.includes('Listening')) return false;

return true;

const vc = window.__ai4a11yVoiceCommands;
if (!vc || !vc.enabled) return true;

const navCatalog = document.getElementById('nav-catalog');
const navReviews = document.getElementById('nav-reviews');
const btnNotice = document.getElementById('btn-close-notice');
const btnAddCart = document.getElementById('btn-add-cart');
if (!navCatalog || !navReviews || !btnNotice || !btnAddCart) return false;

document.body.focus();

// 1. Next link navigation
vc.executeCommand('next link');
if (document.activeElement !== navCatalog) return false;
vc.executeCommand('next link');
if (document.activeElement !== navReviews) return false;

// 2. Previous link navigation
vc.executeCommand('previous link');
if (document.activeElement !== navCatalog) return false;

// Verify visible focus on link
const linkOutline = parseFloat(window.getComputedStyle(navCatalog).outlineWidth) || 0;
if (linkOutline < 2) return false;

// 3. Next button navigation
document.body.focus();
vc.executeCommand('next button');
if (document.activeElement !== btnNotice) return false;
vc.executeCommand('next button');
if (document.activeElement !== btnAddCart) return false;

// 4. Previous button navigation
vc.executeCommand('previous button');
if (document.activeElement !== btnNotice) return false;

// Verify visible focus on button
const btnOutline = parseFloat(window.getComputedStyle(btnNotice).outlineWidth) || 0;
if (btnOutline < 2) return false;

document.activeElement.blur();
return true;

const vc = window.__ai4a11yVoiceCommands;
if (!vc || !vc.enabled) return true;

const cartStatus = document.getElementById('cart-status');
const noticeBanner = document.getElementById('notice-banner');
const quickView = document.getElementById('btn-quickview');
const btnAdd = document.getElementById('btn-add-cart');
if (!cartStatus || !noticeBanner || !quickView || !btnAdd) return false;

// 1. Click button by visible text
const initialCart = cartStatus.textContent;
const clickedAdd = vc.executeCommand('click add to cart');
if (!clickedAdd || !cartStatus.textContent.includes('Cart: 1')) return false;

// 2. Click button by aria-label
const clickedCheckout = vc.executeCommand('click proceed to checkout');
if (!clickedCheckout) return false;

// 3. Click button by aria-labelledby
const clickedDetails = vc.executeCommand('click view comprehensive book details');
if (!clickedDetails) return false;

// 4. Click icon button by title
const clickedClose = vc.executeCommand('click close notification');
if (!clickedClose || noticeBanner.style.display !== 'none') return false;

// 5. Click custom role="button" element
const clickedCustom = vc.executeCommand('click quick view');
if (!clickedCustom || quickView.getAttribute('data-clicked') !== 'true') return false;

// 6. Bare click command on focused element
btnAdd.focus();
const clickedBare = vc.executeCommand('click');
if (!clickedBare || !cartStatus.textContent.includes('Cart: 2')) return false;

// 7. Non-existent control announcement test
const clickedMissing = vc.executeCommand('click imaginary moon rocket');
if (clickedMissing) return false;

// Reset page modifications exactly
cartStatus.textContent = initialCart;
noticeBanner.style.display = '';
quickView.removeAttribute('data-clicked');
document.activeElement.blur();

return true;

const vc = window.__ai4a11yVoiceCommands;
if (!vc || !vc.enabled) return true;

const searchInput = document.getElementById('search-input');
const orderNotes = document.getElementById('order-notes');
const btnAdd = document.getElementById('btn-add-cart');
if (!searchInput || !orderNotes || !btnAdd) return false;

// 1. Click to select/focus input field
const clickedSearch = vc.executeCommand('click search catalog');
if (!clickedSearch || document.activeElement !== searchInput) return false;

// 2. Type into selected input field
let inputFired = false;
const onInput = () => { inputFired = true; };
searchInput.addEventListener('input', onInput);
const typedSearch = vc.executeCommand('type accessibility guide');
searchInput.removeEventListener('input', onInput);

if (!typedSearch || !inputFired || searchInput.value !== 'accessibility guide') return false;

// What was typed is not a field's name: a field named only by its
// title keeps that name once it has text in it.
const filter = document.getElementById('quick-filter');
if (!filter) return false;
if (!vc.executeCommand('click filter titles') || document.activeElement !== filter) return false;
vc.executeCommand('type poetry');
filter.blur();
const refound = vc.executeCommand('click filter titles') && document.activeElement === filter;
filter.value = '';
if (!refound) return false;

// 3. Click to select textarea by associated label text
const clickedNotes = vc.executeCommand('click special instructions');
if (!clickedNotes || document.activeElement !== orderNotes) return false;

// 4. Type into textarea
const typedNotes = vc.executeCommand('type handle with care');
if (!typedNotes || orderNotes.value !== 'handle with care') return false;

// 5. Typing guard when focused on non-text control
btnAdd.focus();
const typedButton = vc.executeCommand('type should not work');
if (typedButton) return false;

// Reset input fields
searchInput.value = '';
orderNotes.value = '';
document.activeElement.blur();

return true;

const vc = window.__ai4a11yVoiceCommands;
if (!vc || !vc.enabled) return true;

window.scrollTo(0, 0);
await new Promise(r => setTimeout(r, 50));

// 1. Spatial scroll commands
vc.executeCommand('scroll down');
await new Promise(r => setTimeout(r, 50));
const scrolledY = window.scrollY;

vc.executeCommand('go to top');
await new Promise(r => setTimeout(r, 50));
if (window.scrollY !== 0 || scrolledY <= 0) return false;

// 2. Stop listening command disables the adapter
const stopped = vc.executeCommand('stop listening');
if (!stopped || vc.enabled) return false;
if (document.getElementById('ai4a11y-voice-feedback')) return false;

// Re-enable so the verifier can perform preview teardown cleanly
vc.enable();
return vc.enabled;

const vc = window.__ai4a11yVoiceCommands;
if (!vc || !vc.enabled) return true;

const feedback = document.getElementById('ai4a11y-voice-feedback');
if (!feedback) return false;

// 1. Pointer events must be none so underlying page remains clickable
const comp = window.getComputedStyle(feedback);
if (comp.pointerEvents !== 'none') return false;

// 2. Text styling and contrast verification
const textSpan = feedback.querySelector('.ai4a11y-voice-text');
if (!textSpan) return false;

// Normal state: color should be white
if (window.getComputedStyle(textSpan).color !== 'rgb(255, 255, 255)') return false;

// Interim state
vc.showFeedback('Interim text...', 'interim');
if (window.getComputedStyle(textSpan).color !== 'rgb(204, 204, 204)') return false;

// Error state
vc.showFeedback('Microphone unavailable', 'error');
if (window.getComputedStyle(textSpan).color !== 'rgb(255, 155, 155)') return false;

// Reset feedback text
vc.showFeedback('Listening...', 'normal');
return true;

const h1 = document.querySelector('header h1');
const nav = document.querySelector('nav[aria-label="Main Navigation"]');
const mainH2 = document.querySelector('main h2');
const asideH2 = document.querySelector('aside h2');
const footerP = document.querySelector('footer p');

if (!h1 || !nav || !mainH2 || !asideH2 || !footerP) return false;
if (h1.textContent !== 'Aptly Accessible Books') return false;
if (nav.children.length !== 3) return false;
if (mainH2.textContent !== 'Featured Titles') return false;
if (asideH2.textContent !== 'Support & Inquiries') return false;
if (!footerP.textContent.includes('Aptly Accessible Books')) return false;

return true;
